<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
const settings=ref([]),purposes=ref([]),banks=ref([]),loading=ref(true),success=ref(null),error=ref(''),qrOpen=ref(false)
const form=reactive({donor_name:'',mobile:'',amount:'',donation_purpose_id:'',payment_method:'bkash',bank_account_id:'',transaction_id:'',payment_screenshot:null,note:''})
const activeSetting=computed(()=>settings.value.find(s=>s.method===form.payment_method))
onMounted(async()=>{try{const[s,p]=await Promise.all([fetch('/api/donation-settings').then(r=>r.json()),fetch('/api/donation-purposes').then(r=>r.json())]);settings.value=s.payment_settings;banks.value=s.bank_accounts;purposes.value=p}finally{loading.value=false}})
async function submit(){error.value='';const data=new FormData;Object.entries(form).forEach(([k,v])=>{if(v!==null&&v!=='')data.append(k,v)});const r=await fetch('/api/donations',{method:'POST',body:data,headers:{Accept:'application/json'}}),j=await r.json();if(!r.ok){error.value=Object.values(j.errors||{}).flat()[0]||'তথ্য জমা দেওয়া যায়নি।';return}success.value=j.donation}
async function copyNumber(){if(activeSetting.value?.number)await navigator.clipboard.writeText(activeSetting.value.number)}
</script>
<template><section class="page-intro"><p class="eyebrow">🙏 দান করুন</p><h1>আপনার সহমর্মী দান</h1><p>আপনার মূল্যবান দান বিহারের ধর্মীয়, সামাজিক, শিক্ষামূলক ও সেবামূলক কার্যক্রমে সহায়তা করবে।</p></section><section v-if="success" class="form-wrap"><div class="success"><i>✓</i><h2>আপনার দানের তথ্য সফলভাবে জমা হয়েছে।</h2><p>আপনার পেমেন্ট যাচাই করা হচ্ছে। যাচাই সম্পন্ন হলে আপনার অনলাইন দানের রসিদ পাওয়া যাবে।</p><dl><dt>রসিদ নম্বর</dt><dd>{{success.receipt_number}}</dd><dt>পরিমাণ</dt><dd>৳ {{success.amount}}</dd><dt>অবস্থা</dt><dd>যাচাই করা হচ্ছে</dd></dl><RouterLink to="/donation-status" class="button primary">দানের অবস্থা দেখুন</RouterLink></div></section><section v-else class="form-wrap"><div v-if="loading" class="loading">তথ্য লোড হচ্ছে…</div><form v-else @submit.prevent="submit"><div class="method-tabs"><button v-for="method in ['bkash','nagad','bank']" :key="method" type="button" :class="{selected:form.payment_method===method}" @click="form.payment_method=method;qrOpen=false">{{method==='bkash'?'বিকাশ':method==='nagad'?'নগদ':'ব্যাংক'}}</button></div><div class="payment-card"><template v-if="form.payment_method==='bank'"><label>ব্যাংক নির্বাচন করুন<select v-model="form.bank_account_id" required><option value="">একটি ব্যাংক বেছে নিন</option><option v-for="bank in banks" :key="bank.id" :value="bank.id">{{bank.bank_name}} — {{bank.account_name}}</option></select></label></template><template v-else-if="activeSetting"><div class="public-payment-info"><div><b>{{form.payment_method==='bkash'?'bKash':'Nagad'}} পেমেন্ট</b><p>নম্বর: <strong>{{activeSetting.number}}</strong></p><p v-if="activeSetting.account_type">অ্যাকাউন্ট: {{activeSetting.account_type}}</p><p v-if="activeSetting.instructions">{{activeSetting.instructions}}</p><button type="button" class="copy-payment" @click="copyNumber">নম্বর কপি করুন</button></div><button v-if="activeSetting.qr_code_url" type="button" class="public-qr" @click="qrOpen=true"><img :src="activeSetting.qr_code_url" :alt="`${activeSetting.method} QR code`"><small>বড় করে দেখুন</small></button></div></template><p v-else>এই পেমেন্ট পদ্ধতি বর্তমানে সক্রিয় নেই।</p></div><h2>দানের তথ্য</h2><div class="form-grid"><label>দাতার নাম<input v-model="form.donor_name" required></label><label>মোবাইল নম্বর<input v-model="form.mobile" placeholder="01XXXXXXXXX" required></label><label>দানের পরিমাণ (৳)<input v-model="form.amount" type="number" min="1" required></label><label>দানের উদ্দেশ্য<select v-model="form.donation_purpose_id" required><option value="">নির্বাচন করুন</option><option v-for="purpose in purposes" :key="purpose.id" :value="purpose.id">{{purpose.name_bn}}</option></select></label><label v-if="form.payment_method!=='bank'">লেনদেনের আইডি<input v-model="form.transaction_id" required></label><label>পেমেন্টের প্রমাণ <small v-if="form.payment_method==='bank'">(আবশ্যক)</small><input type="file" accept="image/jpeg,image/png,image/webp" @change="form.payment_screenshot=$event.target.files[0]" :required="form.payment_method==='bank'"></label></div><label>মন্তব্য (ঐচ্ছিক)<textarea v-model="form.note" rows="3"></textarea></label><p v-if="error" class="error">{{error}}</p><button class="button primary submit">আমি দান করেছি</button></form></section><div v-if="qrOpen&&activeSetting?.qr_code_url" class="qr-modal" role="dialog" aria-modal="true" @click.self="qrOpen=false"><div><button type="button" aria-label="বন্ধ করুন" @click="qrOpen=false">✕</button><h2>{{activeSetting.method==='bkash'?'bKash':'Nagad'}} QR কোড</h2><img :src="activeSetting.qr_code_url" alt="Payment QR code"><p>QR কোড স্ক্যান করে পেমেন্ট করুন</p></div></div></template>
